// Auto-generated from public/control-panel.html for Wrangler compatibility.
export const CONTROL_PANEL_HTML = "<!DOCTYPE html>\n<html dir=\"rtl\" lang=\"ar\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Nexus Control Panel</title>\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      background: #0b0e14;\n      color: #eee;\n      font-family: 'Segoe UI', Tahoma, sans-serif;\n      min-height: 100vh;\n      padding: 20px;\n    }\n    .container { max-width: 1400px; margin: 0 auto; }\n    header {\n      text-align: center;\n      margin-bottom: 30px;\n      border-bottom: 2px solid #f0b90b;\n      padding-bottom: 15px;\n    }\n    h1 { color: #f0b90b; font-size: 2.2em; }\n    .section-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n      gap: 20px;\n      margin-bottom: 30px;\n    }\n    .card {\n      background: #1a1e26;\n      border-radius: 12px;\n      padding: 20px;\n      border-left: 4px solid #f0b90b;\n      box-shadow: 0 2px 15px rgba(0,0,0,0.3);\n    }\n    .card h2 {\n      color: #f0b90b;\n      font-size: 1.1em;\n      margin-bottom: 12px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .status-dot {\n      display: inline-block;\n      width: 12px;\n      height: 12px;\n      border-radius: 50%;\n      margin-left: 8px;\n    }\n    .status-ok { background: #27ae60; }\n    .status-warning { background: #f39c12; animation: pulse 1s infinite; }\n    .status-error { background: #e74c3c; animation: pulse 0.5s infinite; }\n    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }\n    \n    .endpoint-list {\n      list-style: none;\n      padding: 0;\n      margin: 0;\n    }\n    .endpoint-item {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 8px 0;\n      border-bottom: 1px solid #2a2e38;\n      font-size: 0.9em;\n    }\n    .endpoint-item:last-child { border-bottom: none; }\n    .endpoint-name { flex: 1; }\n    .endpoint-status {\n      display: inline-block;\n      width: 8px;\n      height: 8px;\n      border-radius: 50%;\n      margin-left: 10px;\n    }\n    \n    .stat-row {\n      display: flex;\n      justify-content: space-between;\n      padding: 8px 0;\n      border-bottom: 1px solid #2a2e38;\n      font-size: 0.85em;\n    }\n    .stat-row:last-child { border-bottom: none; }\n    .stat-label { color: #aaa; }\n    .stat-value { color: #f0b90b; font-weight: bold; }\n    \n    .button-group {\n      display: flex;\n      gap: 10px;\n      margin-top: 15px;\n      flex-wrap: wrap;\n    }\n    button {\n      background: #f0b90b;\n      color: #000;\n      border: none;\n      padding: 8px 16px;\n      border-radius: 6px;\n      font-weight: bold;\n      cursor: pointer;\n      font-size: 0.85em;\n      transition: opacity 0.2s;\n    }\n    button:hover { opacity: 0.85; }\n    button:disabled { opacity: 0.5; cursor: not-allowed; }\n    \n    .loading {\n      display: inline-block;\n      animation: spin 1s linear infinite;\n    }\n    @keyframes spin { to { transform: rotate(360deg); } }\n    \n    .warning-box {\n      background: #f39c12;\n      color: #000;\n      padding: 12px;\n      border-radius: 6px;\n      margin-top: 10px;\n      font-size: 0.85em;\n    }\n    .error-box {\n      background: #e74c3c;\n      color: #fff;\n      padding: 12px;\n      border-radius: 6px;\n      margin-top: 10px;\n      font-size: 0.85em;\n    }\n    .success-box {\n      background: #27ae60;\n      color: #fff;\n      padding: 12px;\n      border-radius: 6px;\n      margin-top: 10px;\n      font-size: 0.85em;\n    }\n    \n    .code-block {\n      background: #12161e;\n      padding: 10px;\n      border-radius: 6px;\n      font-family: monospace;\n      font-size: 0.75em;\n      overflow-x: auto;\n      margin-top: 8px;\n      white-space: pre-wrap;\n      word-break: break-all;\n    }\n  </style>\n</head>\n<body>\n  <div class=\"container\">\n    <header>\n      <h1>🔷 Nexus Control Panel</h1>\n      <p>منظومة التحكم المركزية - مراقبة الخوادم والاستراتيجيات</p>\n    </header>\n\n    <div class=\"section-grid\">\n      <!-- API Health Check -->\n      <div class=\"card\">\n        <h2>\n          🔗 API Endpoints\n          <span class=\"status-dot\" id=\"api-status-dot\"></span>\n        </h2>\n        <ul class=\"endpoint-list\" id=\"api-list\">\n          <li class=\"endpoint-item\">\n            <span class=\"endpoint-name\">Checking...</span>\n            <span class=\"loading\">⟳</span>\n          </li>\n        </ul>\n        <div class=\"button-group\">\n          <button onclick=\"checkAllEndpoints()\">Refresh</button>\n        </div>\n      </div>\n\n      <!-- BitMart Status -->\n      <div class=\"card\">\n        <h2>\n          💳 BitMart Exchange\n          <span class=\"status-dot\" id=\"bitmart-status-dot\"></span>\n        </h2>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Circuit Breaker:</span>\n          <span class=\"stat-value\" id=\"bitmart-circuit\">Unknown</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Rate Limit:</span>\n          <span class=\"stat-value\" id=\"bitmart-ratelimit\">Unknown</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">External Proxy:</span>\n          <span class=\"stat-value\" id=\"bitmart-proxy\">Disabled</span>\n        </div>\n        <div class=\"button-group\">\n          <button onclick=\"checkBitmartStatus()\">Check Status</button>\n          <button onclick=\"resetBitmartCircuitBreaker()\">Reset CB</button>\n        </div>\n      </div>\n\n      <!-- Proxy Configuration -->\n      <div class=\"card\">\n        <h2>\n          🌐 Proxy Configuration\n          <span class=\"status-dot\" id=\"proxy-status-dot\"></span>\n        </h2>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Local Pool Mode:</span>\n          <span class=\"stat-value\" id=\"proxy-local-mode\">Unknown</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Available Proxies:</span>\n          <span class=\"stat-value\" id=\"proxy-available\">Unknown</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">External Provider:</span>\n          <span class=\"stat-value\" id=\"proxy-external-provider\">None</span>\n        </div>\n        <div class=\"button-group\">\n          <button onclick=\"checkProxyStats()\">Check Stats</button>\n        </div>\n      </div>\n\n      <!-- Strategy Execution -->\n      <div class=\"card\">\n        <h2>\n          ⚡ Strategy Execution\n          <span class=\"status-dot\" id=\"strategy-status-dot\"></span>\n        </h2>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Mode:</span>\n          <span class=\"stat-value\" id=\"strategy-mode\">Unknown</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Active Strategies:</span>\n          <span class=\"stat-value\" id=\"strategy-count\">Unknown</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Portfolio Balance:</span>\n          <span class=\"stat-value\" id=\"strategy-balance\">Unknown</span>\n        </div>\n        <div class=\"button-group\">\n          <button onclick=\"startExecution()\">▶ Start</button>\n          <button onclick=\"stopExecution()\">⏹ Stop</button>\n          <button onclick=\"checkExecutionHealth()\">Status</button>\n        </div>\n      </div>\n\n      <!-- Auto Executor Stats -->\n      <div class=\"card\">\n        <h2>\n          🤖 Auto Executor\n          <span class=\"status-dot\" id=\"executor-status-dot\"></span>\n        </h2>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Paper Mode:</span>\n          <span class=\"stat-value\" id=\"executor-paper\">Unknown</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Max Positions:</span>\n          <span class=\"stat-value\" id=\"executor-positions\">Unknown</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Strategy Cooldown:</span>\n          <span class=\"stat-value\" id=\"executor-cooldown\">Unknown</span>\n        </div>\n        <div class=\"button-group\">\n          <button onclick=\"togglePaperMode()\">Paper Mode</button>\n          <button onclick=\"checkExecutorStats()\">Stats</button>\n        </div>\n      </div>\n\n      <!-- Frontend Connectivity -->\n      <div class=\"card\">\n        <h2>\n          📡 Frontend Check\n          <span class=\"status-dot\" id=\"frontend-status-dot\"></span>\n        </h2>\n        <div id=\"frontend-info\" class=\"stat-row\">\n          Checking connectivity...\n        </div>\n        <div class=\"button-group\">\n          <button onclick=\"checkFrontendConnectivity()\">Verify</button>\n          <button onclick=\"location.href='/dashboard'\">Dashboard</button>\n        </div>\n      </div>\n    </div>\n\n    <!-- Messages Area -->\n    <div id=\"messages\"></div>\n  </div>\n\n  <script>\n    const API_BASE = window.location.origin;\n    const ADMIN_TOKEN = localStorage.getItem('adminToken') || '';\n\n    async function makeRequest(endpoint, options = {}) {\n      try {\n        const resp = await fetch(`${API_BASE}${endpoint}`, {\n          headers: { 'Authorization': `Bearer ${ADMIN_TOKEN}`, ...options.headers },\n          credentials: 'same-origin',\n          ...options,\n        });\n        const text = await resp.text();\n        let data = {};\n        try {\n          data = text ? JSON.parse(text) : {};\n        } catch {\n          data = { message: text };\n        }\n        if (!resp.ok) {\n          return {\n            error: data.error || data.message || text || `HTTP ${resp.status}`,\n            status: resp.status,\n            data,\n          };\n        }\n        if (data && typeof data === 'object') return data;\n        return { success: true, message: text };\n      } catch (err) {\n        console.error(`Request failed: ${err.message}`);\n        return { error: err.message };\n      }\n    }\n\n    function showMessage(text, type = 'info') {\n      const msg = document.createElement('div');\n      msg.className = `${type}-box`;\n      msg.textContent = text;\n      msg.style.marginTop = '20px';\n      document.getElementById('messages').appendChild(msg);\n      setTimeout(() => msg.remove(), 5000);\n    }\n\n    async function checkAllEndpoints() {\n      const endpoints = [\n        '/api/status',\n        '/api/health',\n        '/api/proxy-stats',\n        '/api/balances',\n        '/api/platforms',\n        '/api/execution-health',\n        '/api/analytics',\n        '/api/performance',\n      ];\n\n      const list = document.getElementById('api-list');\n      list.innerHTML = '';\n\n      let successCount = 0;\n      for (const ep of endpoints) {\n        const item = document.createElement('li');\n        item.className = 'endpoint-item';\n        const name = document.createElement('span');\n        name.className = 'endpoint-name';\n        name.textContent = ep;\n        const status = document.createElement('span');\n        status.className = 'endpoint-status status-warning';\n        item.appendChild(name);\n        item.appendChild(status);\n        list.appendChild(item);\n\n        try {\n          const resp = await fetch(`${API_BASE}${ep}`, {\n            headers: { 'Authorization': `Bearer ${ADMIN_TOKEN}` }\n          });\n          status.className = `endpoint-status ${resp.ok ? 'status-ok' : 'status-error'}`;\n          if (resp.ok) successCount += 1;\n        } catch {\n          status.className = 'endpoint-status status-error';\n        }\n      }\n\n      const dotState = successCount === endpoints.length\n        ? 'status-ok'\n        : successCount > 0\n          ? 'status-warning'\n          : 'status-error';\n      document.getElementById('api-status-dot').className = `status-dot ${dotState}`;\n    }\n\n    async function checkBitmartStatus() {\n      const payload = await makeRequest('/api/bitmart/stats');\n      const data = payload?.data || {};\n      if (!data.error) {\n        const circuitState = String(data.circuitBreakerState || '').toUpperCase();\n        document.getElementById('bitmart-circuit').textContent = circuitState === 'OPEN' ? '🔴 OPEN' : '🟢 CLOSED';\n        const used = data.rateLimitUsed ?? data.rateLimitRequests ?? 0;\n        const max = data.rateLimitLimit ?? data.rateLimitMaxPerWindow ?? 'N/A';\n        document.getElementById('bitmart-ratelimit').textContent = `${used}/${max}`;\n        const proxyOn = data.externalProxyEnabled ?? data.externalProxyActive ?? false;\n        document.getElementById('bitmart-proxy').textContent = proxyOn ? '🟢 Enabled' : '⚪ Disabled';\n        document.getElementById('bitmart-status-dot').className = 'status-dot status-ok';\n        showMessage('BitMart status checked', 'success');\n      } else {\n        showMessage(`Error: ${payload.error || data.error}`, 'error');\n      }\n    }\n\n    async function resetBitmartCircuitBreaker() {\n      const resp = await makeRequest('/api/bitmart/reset-circuit-breaker', { method: 'POST' });\n      if (!resp.error) {\n        showMessage('Circuit breaker reset', 'success');\n        checkBitmartStatus();\n      } else {\n        showMessage(`Error: ${resp.error}`, 'error');\n      }\n    }\n\n    async function checkProxyStats() {\n      const data = await makeRequest('/api/proxy-stats');\n      if (!data.error) {\n        document.getElementById('proxy-local-mode').textContent = data.proxyRouting?.mode || data.proxyRouting?.routingMode || 'Unknown';\n        document.getElementById('proxy-available').textContent = data.proxyRouting?.availableProxies ?? data.proxyRouting?.totalProxies ?? '0';\n        document.getElementById('proxy-external-provider').textContent = data.proxyRouting?.externalProvider || (data.proxyRouting?.externalEnabled ? 'Enabled' : 'None');\n        document.getElementById('proxy-status-dot').className = 'status-dot status-ok';\n        showMessage('Proxy stats checked', 'success');\n      }\n    }\n\n    async function checkExecutionHealth() {\n      const data = await makeRequest('/api/execution-health');\n      if (!data.error) {\n        const isPaper = data.paperMode ?? data.paperTrading ?? true;\n        const strategyCount = Array.isArray(data.strategies) ? data.strategies.length : (data.executionMode ? 1 : 0);\n        const rawBalance = data.portfolioBalance ?? data.spotBalance?.free ?? data.spotBalance?.total ?? 0;\n        const balance = Number(rawBalance) || 0;\n        document.getElementById('strategy-mode').textContent = isPaper ? '📄 Paper' : '💰 Live';\n        document.getElementById('strategy-count').textContent = String(strategyCount);\n        document.getElementById('strategy-balance').textContent = `$${balance.toFixed(2)}`;\n        document.getElementById('strategy-status-dot').className = 'status-dot status-ok';\n        showMessage('Execution health OK', 'success');\n      }\n    }\n\n    async function checkExecutorStats() {\n      const data = await makeRequest('/api/proxy-stats'); // Uses auto-executor\n      if (!data.error) {\n        const paperMode = data.executorPaperMode ?? data.paperMode ?? true;\n        const openPositions = Array.isArray(data.openPositions) ? data.openPositions.length : (data.openPositions ?? 0);\n        const cooldown = data.strategyHealth?.defaultCooldownMs ?? data.strategyHealth?.cooldownMs ?? 120000;\n        document.getElementById('executor-paper').textContent = paperMode ? '📄 Yes' : '💰 No';\n        document.getElementById('executor-positions').textContent = String(openPositions);\n        document.getElementById('executor-cooldown').textContent = `${cooldown}ms`;\n        document.getElementById('executor-status-dot').className = 'status-dot status-ok';\n        showMessage('Executor stats checked', 'success');\n      }\n    }\n\n    async function startExecution() {\n      const resp = await makeRequest('/start');\n      if (!resp.error) {\n        showMessage('Execution started', 'success');\n        checkExecutionHealth();\n      } else {\n        showMessage(`Error: ${resp.error}`, 'error');\n      }\n    }\n\n    async function stopExecution() {\n      const resp = await makeRequest('/stop');\n      if (!resp.error) {\n        showMessage('Execution stopped', 'success');\n        checkExecutionHealth();\n      } else {\n        showMessage(`Error: ${resp.error}`, 'error');\n      }\n    }\n\n    async function togglePaperMode() {\n      const status = await makeRequest('/api/status');\n      if (status.error) {\n        showMessage(`Error: ${status.error}`, 'error');\n        return;\n      }\n      const toPaper = status.paper_trading === false;\n      const resp = await makeRequest(toPaper ? '/mode/paper' : '/mode/live', { method: 'POST' });\n      if (!resp.error) {\n        showMessage(toPaper ? 'Switched to paper mode' : 'Switched to live mode', 'success');\n        checkExecutionHealth();\n      } else {\n        showMessage(`Error: ${resp.error}`, 'error');\n      }\n    }\n\n    async function checkFrontendConnectivity() {\n      const dot = document.getElementById('frontend-status-dot');\n      const data = await makeRequest('/api/status');\n      const ok = !data.error;\n      dot.className = `status-dot ${ok ? 'status-ok' : 'status-error'}`;\n      showMessage(ok ? 'Frontend connected to backend API' : `Frontend connection failed: ${data.error}`, ok ? 'success' : 'error');\n    }\n\n    // Initial checks on page load\n    window.addEventListener('load', () => {\n      checkAllEndpoints();\n      checkProxyStats();\n      checkExecutionHealth();\n      checkFrontendConnectivity();\n    });\n\n    // Auto-refresh every 30 seconds\n    setInterval(() => {\n      checkAllEndpoints();\n      checkProxyStats();\n      checkExecutionHealth();\n    }, 30000);\n  </script>\n</body>\n</html>\n";
